package com.hs.jxc.it;
import static org.assertj.core.api.Assertions.*;
import com.hs.jxc.common.api.ApiException;import com.hs.jxc.common.context.RequestContext;import com.hs.jxc.pur.PurchaseService;import com.hs.jxc.lgs.LogisticsService;import java.math.BigDecimal;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;
/** Real PostgreSQL business acceptance: source quotas, atomic receipt, periods and FX recovery. */
class SupplyLogisticsIT extends SupplyFixtures {
 @Test void unknownPurchasePricesRejectCreationAtomicallyAndAllowTheSameIntentAfterCorrection(){
  for(boolean explicitNull:List.of(false,true)){
   var line=new LinkedHashMap<String,Object>(Map.of("productId",501,"unit","PCS","qty",2));if(explicitNull)line.put("unitPrice",null);
   var body=Map.<String,Object>of("bookId",601,"supplierId",801,"orderDate","2026-10-15","lines",List.of(line));String intent=key();
   var before=owner.queryForMap("SELECT (SELECT count(*) FROM pur_order) orders,(SELECT count(*) FROM pur_order_line) lines,(SELECT count(*) FROM sys_audit_log) audits,(SELECT count(*) FROM md_product_unit_used) unit_uses");
   assertThatThrownBy(()->pur.create(c(),"orders",body,intent)).isInstanceOf(ApiException.class).extracting("code").isEqualTo("SYS_BAD_REQUEST");
   assertThat(owner.queryForMap("SELECT (SELECT count(*) FROM pur_order) orders,(SELECT count(*) FROM pur_order_line) lines,(SELECT count(*) FROM sys_audit_log) audits,(SELECT count(*) FROM md_product_unit_used) unit_uses")).isEqualTo(before);
   assertThat(owner.queryForObject("SELECT count(*) FROM sys_idempotency WHERE key=?",Integer.class,intent)).isZero();
   line.put("unitPrice",10);var corrected=pur.create(c(),"orders",body,intent);assertThat(corrected).containsEntry("status","DRAFT");assertThat(new BigDecimal(first(corrected).get("unitPrice").toString())).isEqualByComparingTo("10");
  }
 }
 @Test void unknownPurchasePriceEditsLeaveTheOriginalVersionLinesAndAuditIntact(){
  var original=pur.create(c(),"orders",Map.of("bookId",601,"supplierId",801,"orderDate","2026-10-15","lines",List.of(Map.of("productId",501,"unit","PCS","qty",2,"unitPrice",10))),key());
  var before=owner.queryForMap("SELECT (SELECT count(*) FROM sys_audit_log) audits,(SELECT count(*) FROM md_product_unit_used) unit_uses");
  for(boolean explicitNull:List.of(false,true)){
   var line=new LinkedHashMap<String,Object>(Map.of("productId",501,"unit","PCS","qty",3));if(explicitNull)line.put("unitPrice",null);
   assertThatThrownBy(()->pur.update(c(),"orders",id(original),Map.of("version",original.get("version"),"remark","must roll back","lines",List.of(line)))).isInstanceOf(ApiException.class).extracting("code").isEqualTo("SYS_BAD_REQUEST");
   assertThat(pur.get(c(),"orders",id(original))).containsEntry("version",original.get("version")).containsEntry("remark",original.get("remark"));
   assertThat(owner.queryForObject("SELECT qty FROM pur_order_line",BigDecimal.class)).isEqualByComparingTo("2");assertThat(owner.queryForObject("SELECT unit_price FROM pur_order_line",BigDecimal.class)).isEqualByComparingTo("10");
   assertThat(owner.queryForMap("SELECT (SELECT count(*) FROM sys_audit_log) audits,(SELECT count(*) FROM md_product_unit_used) unit_uses")).isEqualTo(before);
  }
 }
 @Test void anExplicitZeroPurchasePriceRemainsValidForCreationAndEditing(){
  var line=Map.<String,Object>of("productId",501,"unit","PCS","qty",2,"unitPrice",0);var original=pur.create(c(),"orders",Map.of("bookId",601,"supplierId",801,"orderDate","2026-10-15","lines",List.of(line)),key());
  assertThat(new BigDecimal(first(original).get("unitPrice").toString())).isZero();var edited=pur.update(c(),"orders",id(original),Map.of("version",original.get("version"),"remark","explicit zero retained","lines",List.of(line)));
  assertThat(edited).containsEntry("status","DRAFT");assertThat(new BigDecimal(first(edited).get("unitPrice").toString())).isZero();assertThat(new BigDecimal(edited.get("totalAmount").toString())).isZero();
 }
 @Test void originalCurrencyAndServerUnitConversionSurviveAndDomesticDoesNotWriteInventory(){var o=order();assertThat(o).containsEntry("currency","CNY");assertThat(new BigDecimal(first(o).get("baseQty").toString())).isEqualByComparingTo("20");assertThat(new BigDecimal(first(o).get("factor").toString())).isEqualByComparingTo("2");domestic(o,12,4,1,true);assertThat(owner.queryForObject("select count(*) from inv_batch",Integer.class)).isZero();assertThat(owner.queryForObject("select qualified_qty from pur_order_line",BigDecimal.class)).isEqualByComparingTo("12");}
 @Test void duplicateDomesticExportAndShipmentSourcesAreRejectedBeforeWriting(){var o=order();var l=Map.of("orderLineId",id(first(o)),"qualifiedQty",2);assertThatThrownBy(()->pur.create(c(),"domestic-receipts",Map.of("orderId",id(o),"lines",List.of(l,l)),key())).isInstanceOf(ApiException.class).extracting("code").isEqualTo("PUR_DUPLICATE_SOURCE");var r=domestic(o,20,0,0,true);var e=Map.of("receiptLineId",id(first(r)),"qty",2);assertThatThrownBy(()->pur.create(c(),"export-nodes",Map.of("declarationNo","D","lines",List.of(e,e)),key())).isInstanceOf(ApiException.class);var ex=export(r,20,true);var sl=Map.of("sourceLineId",id(first(ex)),"baseQty",2);assertThatThrownBy(()->lgs.create(c(),"shipments",Map.of("bookId",601,"destWarehouseId",401,"carrierId",802,"transportMode","AIR","flightNo","F","awbNo","A","lines",List.of(sl,sl)),key())).isInstanceOf(ApiException.class);assertThat(owner.queryForObject("select count(*) from lgs_shipment",Integer.class)).isZero();}
 @Test void competingDomesticConfirmationsAndShipmentReservationsRespectLockedSourceQuota()throws Exception{var o=order();var a=domestic(o,15,0,0,false);var b=domestic(o,15,0,0,false);assertThat(compete(()->pur.action(c(),"domestic-receipts",id(a),"confirm",Map.of(),key()),()->pur.action(c(),"domestic-receipts",id(b),"confirm",Map.of(),key()))).isEqualTo(1);assertThat(owner.queryForObject("select qualified_qty from pur_order_line",BigDecimal.class)).isEqualByComparingTo("15");long rid=owner.queryForObject("select id from pur_domestic_receipt where status='CONFIRMED'",Long.class);var ex=export(pur.get(c(),"domestic-receipts",rid),15,true);assertThat(compete(()->shipment(ex,10),()->shipment(ex,10))).isEqualTo(1);assertThat(owner.queryForObject("select sum(base_qty) from lgs_shipment_line",BigDecimal.class)).isEqualByComparingTo("10");}
 @Test void receiptConservesFourQuantitiesAndConcurrentSameKeyCreatesOneBatchAndOneCost()throws Exception{var d=delivery();var r=receipt(d);String key=key();var pool=Executors.newFixedThreadPool(20);var start=new CountDownLatch(1);try{List<Future<Map<String,Object>>> results=new ArrayList<>();for(int i=0;i<20;i++){String intent=i<10?key:key();results.add(pool.submit(()->{start.await();return lgs.action(c(),"receipts",id(r),"confirm",Map.of(),intent);}));}start.countDown();for(var result:results)assertThat(result.get(30,TimeUnit.SECONDS)).containsEntry("status","CONFIRMED");}finally{pool.shutdownNow();}assertThat(owner.queryForObject("select count(*) from inv_batch",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("select count(*) from cst_inbound_cost",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("select on_hand_qty from inv_stock_summary",BigDecimal.class)).isEqualByComparingTo("9");assertThat(owner.queryForObject("select frozen_qty from inv_stock_summary",BigDecimal.class)).isEqualByComparingTo("2");assertThat(owner.queryForObject("select arrived_mx_qty from pur_order_line",BigDecimal.class)).isEqualByComparingTo("9");assertThat(owner.queryForObject("select src_amount from cst_inbound_cost",BigDecimal.class)).isEqualByComparingTo("45");assertThat(owner.queryForObject("select count(*) from lgs_shipment_line where shipped_qty=intl_qty+pending_delivery_qty+on_hold_qty+delivering_qty+received_good_qty+received_frozen_qty+discrepancy_qty",Integer.class)).isEqualTo(1);assertThatThrownBy(()->lgs.action(c(),"receipts",id(r),"confirm",Map.of("remark","changed"),key)).isInstanceOf(ApiException.class).extracting("code").isEqualTo("SYS_IDEMPOTENCY_CONFLICT");}
 @Test void failedReceiptRollsBackBatchFreezeCostPurchaseCumulativeAndOutboxThenSameKeyRetries(){var d=delivery();var r=receipt(d);String key=key();owner.execute("create function test_reject_supply_event() returns trigger language plpgsql as $$ begin if NEW.event_type='LGS_RECEIPT_CONFIRMED' then raise exception 'injected receipt rollback'; end if; return NEW; end $$");owner.execute("create trigger test_reject_supply_event before insert on sys_biz_event for each row execute function test_reject_supply_event()");try{assertThatThrownBy(()->lgs.action(c(),"receipts",id(r),"confirm",Map.of(),key)).isInstanceOf(RuntimeException.class);assertThat(owner.queryForObject("select count(*) from inv_batch",Integer.class)).isZero();assertThat(owner.queryForObject("select count(*) from inv_freeze",Integer.class)).isZero();assertThat(owner.queryForObject("select count(*) from cst_inbound_cost",Integer.class)).isZero();assertThat(owner.queryForObject("select arrived_mx_qty from pur_order_line",BigDecimal.class)).isZero();assertThat(owner.queryForObject("select count(*) from sys_idempotency where key=?",Integer.class,key)).isZero();}finally{owner.execute("drop trigger test_reject_supply_event on sys_biz_event");owner.execute("drop function test_reject_supply_event()");}lgs.action(c(),"receipts",id(r),"confirm",Map.of(),key);assertThat(owner.queryForObject("select count(*) from inv_batch",Integer.class)).isEqualTo(1);}
 @Test void receiptMismatchAndClosedDateAreRejectedWithoutPartialFacts(){var r=receipt(delivery());long line=id(first(r));assertThatThrownBy(()->lgs.action(c(),"receipts",id(r),"confirm",Map.of("lines",List.of(Map.of("id",line,"goodQty",6))),key())).isInstanceOf(ApiException.class).extracting("code").isEqualTo("LGS_RECEIPT_QTY_MISMATCH");assertThat(owner.queryForObject("select good_qty from lgs_receipt_line",BigDecimal.class)).isEqualByComparingTo("7");seed("update fin_period set status='CLOSED' where id=701");assertThatThrownBy(()->lgs.action(c(),"receipts",id(r),"confirm",Map.of(),key())).isInstanceOf(ApiException.class);assertThatThrownBy(()->inCountry(101,()->jdbc.update("update lgs_receipt_line set good_qty=8 where id=?",line))).isInstanceOf(RuntimeException.class);assertThat(owner.queryForObject("select count(*) from inv_batch",Integer.class)).isZero();}
 @Test void pendingRateFeeUsesOriginalConfirmToRecoverAndPreservesCapitalizationSource(){var d=delivery();long sid=((Number)d.get("shipmentId")).longValue();var b=Map.<String,Object>of("shipmentId",sid,"refType","SHIPMENT","refId",sid,"carrierId",802,"expenseItemId",803,"currency","CNY","amount",100,"estimateFlag","ACTUAL","bizDate","2026-10-15");var f=lgs.create(c(),"fees",b,key());String initial=key();var pending=lgs.action(c(),"fees",id(f),"confirm",Map.of(),initial);assertThat(pending).containsEntry("status","CONFIRMED").containsEntry("costStatus","PENDING_RATE");assertThat(pending.get("baseAmount")).isNull();seed("insert into md_exchange_rate(country_id,from_ccy,to_ccy,rate_date,scope,rate,status,confirmed_by,confirmed_at) values(101,'CNY','MXN','2026-10-15','PURCHASE_COST',2.5,'CONFIRMED',201,clock_timestamp())");assertThat(lgs.action(c(),"fees",id(f),"confirm",Map.of(),initial)).containsEntry("costStatus","PENDING_RATE");var ready=lgs.action(c(),"fees",id(f),"confirm",Map.of(),key());assertThat(ready).containsEntry("costStatus","READY");assertThat(new BigDecimal(ready.get("baseAmount").toString())).isEqualByComparingTo("250");assertThat(String.valueOf(ready.get("costSource"))).contains("CAPITALIZE","originalCurrency","originalAmount","rateId");assertThat(owner.queryForObject("select count(*) from sys_biz_event where event_type='LGS_FEE_CONFIRMED'",Integer.class)).isEqualTo(1);assertThat(owner.queryForObject("select count(*) from sys_biz_event where event_type='LGS_FEE_COST_READY'",Integer.class)).isEqualTo(1);}

}
